def read_file_line_by_line(file_path):
    try:
        with open(file_path, 'r') as file:
            for line in file:
                try:
                    yield line.strip()
                except Exception as e:
                    # 如果在生成器中遇到异常，可以选择处理或者传播
                    yield f"Error processing line: {str(e)}"
    except FileNotFoundError as e:
        raise ValueError(f"File not found: {str(e)}")

# 使用生成器逐行读取文件
gen = read_file_line_by_line("example.txt")

for line in gen:
    if "Error" in line:
        gen.throw(ValueError("Error found in line"))  # 在生成器中引发异常
    print(line)
